N = 332
R = [('year_ratings_compare_mode_0', 'year_ratings_compare_mode_0', '0x931f90', 'award/year_ratings.cpp', 'cdecl', 'ordem do modo 0 (a soma +8 dobrada): entrada com menos de 3 partidas vai depois de uma com 3 ou mais (duas assim empatam); senão a pontuação maior primeiro; pontuação (gols + 2 × a soma de notas do modo + as outras duas) / partidas + 2 × partidas × 0,02; × 1,2 para quem tem atacante acima de 14, senão × 1,05 com meia-atacante acima de 14', "order of mode 0 (the +8 sum doubled): an entry with fewer than 3 matches goes after one with 3 or more (two such are equal); otherwise the higher score first; score (goals + 2 × the mode's rating sum + the other two) / matches + 2 × matches × 0.02; × 1.2 for an attacker rated above 14, else × 1.05 for an attacking midfielder above 14"), ('year_ratings_compare_mode_1', 'year_ratings_compare_mode_1', '0x9320e0', 'award/year_ratings.cpp', 'cdecl', 'ordem do modo 1 (a soma +0xa dobrada), como o modo 0', 'order of mode 1 (the +0xa sum doubled), as mode 0'), ('year_ratings_compare_mode_2', 'year_ratings_compare_mode_2', '0x932230', 'award/year_ratings.cpp', 'cdecl', 'ordem do modo 2 (a soma +0xc dobrada), como o modo 0, e a pontuação vezes a habilidade atual × 0,00625 de quem tem ficha de jogador', 'order of mode 2 (the +0xc sum doubled), as mode 0, and the score times the current ability × 0.00625 for a player with a sheet'), ('year_ratings_compare_mode_3', 'year_ratings_compare_mode_3', '0x9323b0', 'award/year_ratings.cpp', 'cdecl', 'ordem do modo 3: entrada com menos de 3 partidas vai depois de uma com 3 ou mais; senão a pontuação maior primeiro; pontuação (5 × gols + 3 × assistências + a soma +0xc) / partidas, × a reputação do clube da pessoa × 0,0002 (com clube) × a habilidade atual × 0,02 (com ficha)', "order of mode 3: an entry with fewer than 3 matches goes after one with 3 or more; otherwise the higher score first; score (5 × goals + 3 × assists + the +0xc sum) / matches, × the reputation of the person's club × 0.0002 (with a club) × the current ability × 0.02 (with a sheet)"), ('year_ratings_compare_mode_4', 'year_ratings_compare_mode_4', '0x932500', 'award/year_ratings.cpp', 'cdecl', 'ordem do modo 4: entrada com menos de 3 partidas vai depois de uma com 3 ou mais; senão a pontuação maior primeiro; pontuação os cartões (amarelos + 2 × vermelhos) por partida', 'order of mode 4: an entry with fewer than 3 matches goes after one with 3 or more; otherwise the higher score first; score the cards (yellows + 2 × reds) per match'), ('year_ratings_compare_mode_5', 'year_ratings_compare_mode_5', '0x932590', 'award/year_ratings.cpp', 'cdecl', 'ordem do modo 5: entrada com menos de 3 partidas vai depois de uma com 3 ou mais; senão a pontuação maior primeiro; pontuação a do modo 3 sem o clube, × (reputação atual × 0,0002 + 4) com ficha, pela metade com determinação, lealdade ou esportividade abaixo de 10', 'order of mode 5: an entry with fewer than 3 matches goes after one with 3 or more; otherwise the higher score first; score that of mode 3 without the club, × (current reputation × 0.0002 + 4) with a sheet, halved with determination, loyalty or sportsmanship below 10'), ('year_ratings_reset_if_year', 'YEAR_RATINGS::reset_if_year', '0x931aa0', 'award/year_ratings.cpp', 'thiscall, ret 4', 'libera as entradas e zera a conta e a capacidade quando o ano dado é o da tabela', "frees the entries and zeroes the count and capacity when the given year is the table's"), ('year_ratings_collect_best_players', 'YEAR_RATINGS::collect_best_players', '0x931ae0', 'award/year_ratings.cpp', 'thiscall, ret 0x24', 'ordena a tabela pelo modo (0 a 5) e coleta até max entradas na ordem, em passadas do mínimo de partidas para baixo de 5 em 5 (enquanto acima de 0), cada uma pegando as entradas com partidas suficientes que ainda não estão nas max vagas da saída e passam nos filtros, até max; devolve quantas. Defeito do original: a conferência de "já pega" lê as max vagas da saída, não só as preenchidas. Mínimo de 25 partidas, 15 no ano civil de 2001; filtros (−1 ou 0xff nenhum): a nacionalidade; a nação do clube; a nacionalidade excluída; a nação do clube e a nacionalidade iguais à de casa; a idade máxima; a divisão do clube', 'sorts the table by mode (0 to 5) and collects up to max entries in order, in passes from the minimum matches down in steps of 5 (while above 0), each taking the entries with enough matches that are not yet among the max output slots and pass the filters, until max; returns how many. Defect of the original: the "already taken" check reads all max output slots, not only the filled ones. Minimum 25 matches, 15 in calendar year 2001; filters (−1 or 0xff none): the nationality; the club\'s nation; the excluded nationality; the club\'s nation and the nationality both the home nation; the maximum age; the club\'s division'), ('year_ratings_collect_candidates', 'YEAR_RATINGS::collect_candidates', '0x931d50', 'award/year_ratings.cpp', 'thiscall, ret 0x18', 'ordena a tabela pelo modo e coleta até max entradas na ordem, em passadas do mínimo de partidas para baixo de 5 em 5 (enquanto acima de 0), cada uma pegando as entradas com partidas suficientes que ainda não estão nas max vagas da saída e passam nos filtros, até max; devolve quantas. Defeito do original: a conferência de "já pega" lê as max vagas da saída, não só as preenchidas. Mínimo de 25 partidas; com continente, a nação da pessoa nele (sem nacionalidade passa), e na América do Sul também o clube numa nação sul-americana; com máscara de posições, quem tem ficha precisa de uma posição natural nela; quem está na lista excluída (pelo id) fica de fora', 'sorts the table by mode and collects up to max entries in order, in passes from the minimum matches down in steps of 5 (while above 0), each taking the entries with enough matches that are not yet among the max output slots and pass the filters, until max; returns how many. Defect of the original: the "already taken" check reads all max output slots, not only the filled ones. Minimum 25 matches; with a continent, the person\'s nation in it (no nationality passes), and for South America also a club of a South American nation; with a position mask, someone with a sheet needs a natural position in it; anyone in the excluded list (by id) is left out'), ('team_award_add_candidate', 'TEAM_AWARD::add_candidate', '0x8afa40', 'award/team_award.cpp', 'thiscall, ret 0x10', 'oferece um jogador à seleção: sem pessoa, ficha ou clube, nada; já escolhido, a nota sobe se for maior; senão as posições (a máscara dada ou a da ficha) são alargadas (2 dá também 4; 8 ou 0x20 dão 0x10; 0x40 com 0x80 ou 0x800 dá 0x200) e ele ocupa a primeira vaga vazia que lhe serve; sem nenhuma, a primeira vaga ocupada que lhe serve cujo ocupante caiba numa vaga vazia: o ocupante muda para ela e ele fica com a vaga. O número da camisa (em módulo) vale quando o clube usa números fixos. Devolve 1 com a seleção completa', "offers a player to the selection: without a person, a sheet or a club, nothing; already chosen, his rating rises when higher; otherwise his positions (the given mask or his sheet's) are widened (2 also gives 4; 8 or 0x20 give 0x10; 0x40 with 0x80 or 0x800 gives 0x200) and he takes the first empty slot that fits him; with none, the first filled slot that fits him whose occupant fits an empty slot: the occupant moves there and he takes the slot. His squad number (absolute) counts when the club uses squad numbers. Returns 1 when the selection is complete"), ('team_award_clear_selection', 'TEAM_AWARD::clear_selection', '0x8afd90', 'award/team_award.cpp', 'thiscall', 'esvazia as 20 vagas (id, ids de nome e clube −1, nota 0; o número fica) e zera a conta das preenchidas', 'empties the 20 slots (id, name ids and club −1, rating 0; the number stays) and zeroes the filled count'), ('team_award_init_slot_positions', 'TEAM_AWARD::init_slot_positions', '0x8afdc0', 'award/team_award.cpp', 'thiscall', 'as máscaras de posição das vagas: os onze pela formação (modos 0, 1 e 2 os seus, qualquer outro o quarto) e os nove reservas sempre goleiro e três vezes (0x40, 4, 0x10)', "the slots' position masks: the eleven by the formation (modes 0, 1 and 2 their own, any other the fourth) and the nine substitutes always goalkeeper then three times (0x40, 4, 0x10)")]
